CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(120) NOT NULL,public_slug varchar(80) UNIQUE NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),email varchar(254) NOT NULL,name varchar(120) NOT NULL,password_hash text NOT NULL,role varchar(20) NOT NULL CHECK(role IN('admin','agent')),active boolean NOT NULL DEFAULT true,UNIQUE(tenant_id,email));
CREATE TABLE tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),protocol integer NOT NULL,requester_name varchar(120) NOT NULL,department varchar(120) NOT NULL,contact varchar(254),title varchar(180) NOT NULL,summary text NOT NULL,product varchar(80) NOT NULL,priority varchar(20) NOT NULL DEFAULT 'normal',status varchar(30) NOT NULL DEFAULT 'new',public_token_hash varchar(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,protocol));
CREATE TABLE resolutions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),ticket_id uuid UNIQUE NOT NULL REFERENCES tickets(id),confirmed_problem text NOT NULL,root_cause text NOT NULL,solution text NOT NULL,validation text NOT NULL,reusable boolean NOT NULL DEFAULT false,sanitized_document jsonb);
CREATE TABLE ai_configs(tenant_id uuid PRIMARY KEY REFERENCES tenants(id),provider varchar(30) NOT NULL DEFAULT 'ollama',model varchar(120) NOT NULL,embedding_model varchar(120) NOT NULL,context_size integer NOT NULL DEFAULT 8192,max_tokens integer NOT NULL DEFAULT 512,temperature varchar(8) NOT NULL DEFAULT '0.2');
CREATE TABLE knowledge_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),title varchar(180) NOT NULL,filename varchar(255) NOT NULL,content_type varchar(100) NOT NULL,sha256 varchar(64) NOT NULL,status varchar(20) NOT NULL DEFAULT 'active',uploaded_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,sha256));
CREATE TABLE knowledge_chunks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),document_id uuid NOT NULL REFERENCES knowledge_documents(id) ON DELETE CASCADE,chunk_index integer NOT NULL,content text NOT NULL,UNIQUE(document_id,chunk_index));
CREATE TABLE ticket_status_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),ticket_id uuid NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,status varchar(30) NOT NULL,changed_by uuid REFERENCES users(id),entered_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE usage_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),event_type varchar(40) NOT NULL,model varchar(120),success boolean NOT NULL DEFAULT true,duration_ms integer,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX tickets_tenant_status_idx ON tickets(tenant_id,status,created_at DESC);CREATE INDEX resolutions_tenant_idx ON resolutions(tenant_id);CREATE INDEX knowledge_documents_tenant_idx ON knowledge_documents(tenant_id,created_at DESC);CREATE INDEX knowledge_chunks_tenant_idx ON knowledge_chunks(tenant_id,document_id);CREATE INDEX ticket_status_history_tenant_idx ON ticket_status_history(tenant_id,ticket_id,entered_at);CREATE INDEX usage_events_tenant_idx ON usage_events(tenant_id,created_at DESC);
ALTER TABLE users ENABLE ROW LEVEL SECURITY;ALTER TABLE users FORCE ROW LEVEL SECURITY;ALTER TABLE tickets ENABLE ROW LEVEL SECURITY;ALTER TABLE tickets FORCE ROW LEVEL SECURITY;ALTER TABLE resolutions ENABLE ROW LEVEL SECURITY;ALTER TABLE resolutions FORCE ROW LEVEL SECURITY;ALTER TABLE ai_configs ENABLE ROW LEVEL SECURITY;ALTER TABLE ai_configs FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_documents ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_documents FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_chunks ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_chunks FORCE ROW LEVEL SECURITY;ALTER TABLE ticket_status_history ENABLE ROW LEVEL SECURITY;ALTER TABLE ticket_status_history FORCE ROW LEVEL SECURITY;ALTER TABLE usage_events ENABLE ROW LEVEL SECURITY;ALTER TABLE usage_events FORCE ROW LEVEL SECURITY;
CREATE POLICY users_tenant ON users USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE POLICY tickets_tenant ON tickets USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE POLICY resolutions_tenant ON resolutions USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE POLICY ai_configs_tenant ON ai_configs USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE POLICY knowledge_documents_tenant ON knowledge_documents USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE POLICY knowledge_chunks_tenant ON knowledge_chunks USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE POLICY ticket_status_history_tenant ON ticket_status_history USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE POLICY usage_events_tenant ON usage_events USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
